#pragma once

#include "gui_forms/binding/property_cell/property_cell.hpp"

#include <cstdint>
#include <optional>
#include <string>
#include <utility>

namespace gui_forms {

// FolderBrowserDialog's property capabilities (property-capabilities study, sections
// 2, 14 and 15). Generated by tools/property_codemod.py from
// tools/property_families/folder_browser_dialog.json: edit the config, not this file.
//
// Each is a standard-layout struct whose only member is its property's
// cell, taken by the declaring class as a base. A write
// `(*control).x = value;` runs `assign`: the declaring class's
// prepare_write hook (require_mutable first, then the value's checks), the
// compare and store, then the written hook (the touch, side effects and the
// change event, through the protected virtual on_<property>_changed() where
// Windows Forms has an overridable On<Property>Changed; other properties
// have no hook, and a subclass subscribes to their change events instead). A read is
// `(*control).x.read()`.

// The text the dialog shows the user: above the tree on Windows, as the title elsewhere. Empty gives the host's own. Valid UTF-8 without NUL (std::invalid_argument).
template <typename Declaring>
struct FolderBrowserDialogDescriptionCapability {
    PropertyCell<std::string, FolderBrowserDialogDescriptionCapability<Declaring>> description{};

    static void assign(FolderBrowserDialogDescriptionCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.description), incoming);
        if (!capability.description.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.description));
    }
};

// The folder the dialog starts in when no folder is selected; empty lets the host choose. Valid UTF-8 without NUL (std::invalid_argument).
template <typename Declaring>
struct FolderBrowserDialogInitialDirectoryCapability {
    PropertyCell<std::string, FolderBrowserDialogInitialDirectoryCapability<Declaring>> initial_directory{};

    static void assign(FolderBrowserDialogInitialDirectoryCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.prepare_write(std::as_const(capability.initial_directory), incoming);
        if (!capability.initial_directory.replace(std::move(incoming))) return;
        control.written(std::as_const(capability.initial_directory));
    }
};

// The chosen folder, or empty. A folder set here before the dialog is shown is the one it starts in; an accepted show_dialog moves it. Valid UTF-8 without NUL (std::invalid_argument).
template <typename Declaring>
struct FolderBrowserDialogSelectedPathCapability {
    PropertyView<std::string, FolderBrowserDialogSelectedPathCapability<Declaring>> selected_path;

    static void assign(FolderBrowserDialogSelectedPathCapability& capability, std::string incoming) {
        Declaring& control = static_cast<Declaring&>(capability);
        control.write_view(std::as_const(capability.selected_path), std::move(incoming));
    }

    static std::string read(const FolderBrowserDialogSelectedPathCapability& capability) {
        const Declaring& control = static_cast<const Declaring&>(capability);
        std::string current = control.read_view(capability.selected_path);
        return current;
    }
};

// Every FolderBrowserDialog capability, in the order the declaring class takes them.
template <typename Declaring>
struct FolderBrowserDialogCapabilities : public FolderBrowserDialogDescriptionCapability<Declaring>,
                                         public FolderBrowserDialogInitialDirectoryCapability<Declaring>,
                                         public FolderBrowserDialogSelectedPathCapability<Declaring> {};

} // namespace gui_forms
